#!/usr/bin/env python3
"""Resolve complete public suite inputs without admitting extension observations."""
from __future__ import annotations

import hashlib
import json
import re
import subprocess
import sys
from pathlib import Path

from check_acceptance_permanent import MANIFEST, suite_assertions

ACCEPTANCE = Path("tests/acceptance")
EXTENSIONS = ACCEPTANCE / "proposals/independent-extension-reconstruction-20261024/completion"
CHECKPOINT = EXTENSIONS / "source-checkpoint.json"
# These complete source files and their checkpoint entered this history together.
# This is input provenance, not a regenerated outcome or assertion baseline.
SOURCE_REVISION = "9a640af2d2c5910dc0aed1e60eaaf0c9e4c4b1df"
ADDED_EXTENSIONS = {
    "rx02-complete-core-action", "rx03-complete-automorphism-arrows",
    "rx-lift-source-comparison",
}
STEM = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")


def parse_selection(arguments: list[str]) -> tuple[str | None, list[dict]]:
    """Resolve names only; the same paths feed preflight, execution and timing."""
    manifest = None
    selected = []
    remaining = iter(arguments)
    for argument in remaining:
        extension = argument == "--extension"
        if argument == "--manifest":
            if manifest is not None:
                raise ValueError("select one manifest")
            manifest = next(remaining, None)
            if manifest is None or manifest.startswith("--"):
                raise ValueError("--manifest requires its original file")
            continue
        if argument == "--all":
            selected.extend({"stem": path.stem, "source": str(path), "kind": "admitted",
                             "key": path.stem} for path in sorted(ACCEPTANCE.glob("*.cas")))
            continue
        stem = next(remaining, None) if extension else argument
        if stem is None or STEM.fullmatch(stem) is None:
            raise ValueError("--extension requires a completion stem" if extension
                             else f"not an acceptance stem: {stem}")
        directory = EXTENSIONS if extension else ACCEPTANCE
        selected.append({"stem": stem, "source": str(directory / f"{stem}.cas"),
                         "kind": "extension" if extension else "admitted",
                         "key": f"extension--{stem}" if extension else stem})
    paths = [item["source"] for item in selected]
    keys = [item["key"] for item in selected]
    if len(set(paths)) != len(paths) or len(set(keys)) != len(keys):
        raise ValueError("select each complete source file once")
    return manifest, selected


def original_blob(path: Path) -> bytes:
    return subprocess.check_output(["git", "show", f"{SOURCE_REVISION}:{path}"])


def checked_input(selected: dict) -> dict:
    """Check the original authority before deriving a completeness-only inventory."""
    source = Path(selected["source"])
    if not source.is_file():
        raise ValueError(f"no {selected['kind']} file {source}")
    digest = hashlib.sha256(source.read_bytes()).hexdigest()
    if selected["kind"] == "extension":
        original = original_blob(CHECKPOINT)
        if CHECKPOINT.read_bytes() != original:
            raise ValueError(f"extension source checkpoint changed: {CHECKPOINT}")
        checkpoint = json.loads(original)["completion_file_sha256"]
        if source.name in checkpoint:
            expected = checkpoint[source.name]
            authority = {"kind": "source-checkpoint", "file": str(CHECKPOINT),
                         "revision": SOURCE_REVISION,
                         "checkpoint_sha256": hashlib.sha256(original).hexdigest()}
        elif selected["stem"] in ADDED_EXTENSIONS:
            data = original_blob(source)
            expected = hashlib.sha256(data).hexdigest()
            authority = {"kind": "added-blob", "revision": SOURCE_REVISION,
                         "blob": subprocess.check_output(
                             ["git", "rev-parse", f"{SOURCE_REVISION}:{source}"],
                             text=True).strip()}
        else:
            raise ValueError(f"no original completion source authority for {source}")
        if digest != expected:
            raise ValueError(f"extension source changed: {source}; "
                             f"expected sha256 {expected}, received {digest}")
        assertions = suite_assertions([source])
        return {**selected, "sha256": digest, "authority": authority,
                "admitted": False, "computing": True, "assertions": assertions}
    admitted = json.loads(MANIFEST.read_text())["assertions"]
    assertions = suite_assertions([source])
    if not assertions:
        raise ValueError(f"no named assertions in {source}")
    for identity, digest_ in assertions.items():
        if admitted.get(identity) != digest_:
            raise ValueError(f"selected assertion is not the unchanged admitted input: {identity}")
    return {**selected, "sha256": digest,
            "authority": {"kind": "admitted-assertions", "file": str(MANIFEST)},
            "admitted": True, "computing": False, "assertions": assertions}


def main() -> int:
    if len(sys.argv) < 2:
        raise SystemExit("usage: acceptance_inputs.py OUTPUT [--manifest FILE] "
                         "[STEM | --extension STEM | --all] ...")
    output = Path(sys.argv[1])
    manifest, selected = parse_selection(sys.argv[2:])
    if not selected:
        raise ValueError("select at least one complete source file")
    document = {"manifest": manifest, "files": selected, "complete": False}
    output.write_text(json.dumps(document, ensure_ascii=False, indent=2) + "\n")
    checked = []
    for item in selected:
        checked.append(checked_input(item))
        document["files"] = checked + selected[len(checked):]
        output.write_text(json.dumps(document, ensure_ascii=False, indent=2) + "\n")
    document["complete"] = True
    output.write_text(json.dumps(document, ensure_ascii=False, indent=2) + "\n")
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except (ValueError, FileNotFoundError, KeyError, subprocess.CalledProcessError) as error:
        raise SystemExit(str(error))

#!/usr/bin/env python3
"""Compare two runs of the acceptance suite, assertion by assertion (B0 gate family C).

    check_acceptance_regression.py BASE.json HEAD.json

Each file is the report `cas-harness --report` writes: one result per test, with its file, id and
outcome kind, optional stratum and explicit failure flag. Missing additive fields retain
legacy behavior. The comparison is by assertion identity, never by counts. The head fails when:
- an assertion of the base is missing from it;
- an assertion the base did not fail (it held, was a gap, or its backend was unavailable) fails at
  the head, or one that held is no longer computed;
- an assertion that is not in the base fails at the head: a new assertion is held to the suite,
  not to the base.
A statement that is not a test (a `let`) and does not hold is reported under its own text, and is
compared like a test. A failing assertion that changes kind is reported, and fails nothing: it was
failing already, and stays a failure to repair (stage A judges regression, not completion).

`cas-harness` writes its report only after the whole suite ran, so a run that did not complete
(a file that does not parse, a crash) leaves no report, and the comparison fails on it.
"""

import json
import sys
from typing import NamedTuple
from pathlib import Path

FAILING = {"wrong", "malformed", "invalid", "ambiguous", "internal"}
KINDS = {"holds", "gap", "unavailable"} | FAILING


class ReportOutcome(NamedTuple):
    kind: str
    stratum: str | None
    fails: bool

    def describe(self) -> str:
        details = [self.stratum] if self.stratum is not None else []
        if self.fails and self.kind not in FAILING:
            details.append("fails")
        return self.kind + (" [" + ", ".join(details) + "]" if details else "")


def report_outcome(result: dict) -> ReportOutcome:
    kind = result["kind"]
    stratum = result.get("stratum")
    explicit = result.get("fails", False)
    if kind not in KINDS or not isinstance(explicit, bool):
        raise ValueError("unknown outcome kind or invalid failure column")
    if stratum is not None and not isinstance(stratum, str):
        raise ValueError("an outcome stratum must be a string or null")
    # Old reports retain their original kind-based behavior. A false/missing flag
    # cannot erase a precise unread-source failure in an additive report.
    return ReportOutcome(kind, stratum,
                         explicit or kind in FAILING or stratum == "unsupportedSource")


def outcomes(path: Path) -> dict[tuple[str, str], ReportOutcome]:
    if not path.is_file():
        sys.exit(f"no report at {path}: the suite did not run to completion")
    results = json.loads(path.read_text())
    if not isinstance(results, list):
        raise ValueError("the suite report must be an array")
    found: dict[tuple[str, str], ReportOutcome] = {}
    for result in results:
        key = (result["file"], result["id"])
        if not all(isinstance(part, str) for part in key):
            raise ValueError("a report row lost its file or assertion identity")
        if key in found:
            sys.exit(f"duplicate assertion in report {path}: {key}")
        found[key] = report_outcome(result)
    return found


def main() -> int:
    if len(sys.argv) != 3:
        print(__doc__, file=sys.stderr)
        return 2
    base, head = outcomes(Path(sys.argv[1])), outcomes(Path(sys.argv[2]))
    # A failing statement (a `let`) is reported only while it fails: absent at the head, it holds.
    missing = sorted(key for key in base if key not in head and not key[1].startswith("(statement)"))
    resolved = sorted(key for key in base if key not in head and key[1].startswith("(statement)"))
    regressed = sorted((key, base[key], head[key]) for key in base
                       if key in head and not base[key].fails and head[key].fails)
    lost = sorted((key, base[key], head[key]) for key in base
                  if key in head and base[key].kind == "holds" and head[key].kind != "holds"
                  and not head[key].fails)
    new_failing = sorted((key, head[key]) for key in head
                         if key not in base and head[key].fails)
    gained = sorted((key, base[key] if key in base else None, head[key]) for key in head
                    if head[key].kind == "holds" and not head[key].fails
                    and (key not in base or base[key].kind != "holds" or base[key].fails))
    rekinded = sorted((key, base[key], head[key]) for key in base
                      if key in head and base[key].fails and head[key].fails
                      and base[key] != head[key])
    for title, rows in (("now holds", gained), ("failing, now of another kind", rekinded),
                        ("held, now not computed", lost)):
        for (file, id_), before, after in rows:
            previous = before.describe() if before is not None else "not previously observed"
            print(f"{title}: {file}: {id_}: {previous} -> {after.describe()}")
    for file, id_ in resolved:
        print(f"statement now holds: {file}: {id_}")
    for file, id_ in missing:
        print(f"MISSING at the head: {file}: {id_}")
    for (file, id_), before, after in regressed:
        print(f"FAILS at the head: {file}: {id_}: {before.describe()} -> {after.describe()}")
    for (file, id_), after in new_failing:
        print(f"NEW and FAILS at the head: {file}: {id_}: {after.describe()}")
    failing = sorted(key for key, outcome in head.items() if outcome.fails)
    print(f"{len(head)} assertions at the head; failing: "
          f"{', '.join(id_ for _, id_ in failing) or 'none'}")
    return 1 if missing or regressed or lost or new_failing else 0


if __name__ == "__main__":
    sys.exit(main())

"""Fair search over finite, source-authorized comparison derivation syntax.

This module implements enumeration and bounded-check scheduling, not mathematics
or a Lean proof checker. The fixed source environment supplies the permissible
syntax constructors and the trusted checker for ONE complete, rigid goal. A leaf
is never that checker and supplies none of this input. The caller must retain the
actual source environment/goal, not just their displayed names or hashes.

Candidate rejection means only that this candidate is not a permitted proof.
Finite search exhaustion is always Pending, never no-reading or disagreement.
A trusted checker must return within its reserved budget; resource exhaustion
must return Deferred, and an internal exception is propagated rather than used
as evidence. A production implementation uses the existing global resource
meter and synchronous Lean kernel checking. These are scheduler reference tests,
not proof that the production checker or original mathematical workload passes.
"""
from __future__ import annotations

from dataclasses import dataclass
from typing import Callable, Generic, TypeVar

Context = TypeVar("Context")
Goal = TypeVar("Goal")
Proof = TypeVar("Proof")


@dataclass(frozen=True)
class Symbol:
    """An engineering syntax constructor; its ID refers to the frozen source."""
    source_id: str
    arity: int

    def __post_init__(self) -> None:
        if not self.source_id or self.arity < 0:
            raise ValueError("a symbol needs a source identity and nonnegative arity")


@dataclass(frozen=True)
class Term:
    symbol: int
    arguments: tuple[Term, ...] = ()


def code_at(index: int, alphabet_size: int) -> tuple[int, ...]:
    """Unrank all finite words in length-then-lexicographic order, including ()."""
    if index < 0 or alphabet_size <= 0:
        raise ValueError("invalid index or empty alphabet")
    length, block = 0, 1
    while index >= block:
        index -= block
        length += 1
        block *= alphabet_size
    digits = [0] * length
    for position in range(length - 1, -1, -1):
        index, digits[position] = divmod(index, alphabet_size)
    return tuple(digits)


def decode(code: tuple[int, ...], alphabet: tuple[Symbol, ...]) -> Term | None:
    """Decode prefix-arity syntax without recursion or implicit symbol lookup."""
    if not code:
        return None
    frames: list[tuple[int, list[Term]]] = []
    root: Term | None = None
    for token in code:
        if root is not None or token < 0 or token >= len(alphabet):
            return None
        frames.append((token, []))
        while frames and len(frames[-1][1]) == alphabet[frames[-1][0]].arity:
            symbol, arguments = frames.pop()
            term = Term(symbol, tuple(arguments))
            if frames:
                frames[-1][1].append(term)
            else:
                root = term
    return root if not frames else None


@dataclass(frozen=True)
class Accepted(Generic[Proof]):
    """Only the trusted, source-bound checker may issue this response."""
    proof: Proof


@dataclass(frozen=True)
class Rejected:
    """A definite rejection of this finite proof candidate, not of the goal."""
    reason: str


@dataclass(frozen=True)
class Deferred:
    """No verdict on this candidate within its allocated checking budget."""
    reason: str = "checking resource exhausted"


@dataclass(frozen=True)
class Found(Generic[Context, Goal, Proof]):
    context: Context
    goal: Goal
    code: tuple[int, ...]
    term: Term
    proof: Proof


@dataclass(frozen=True)
class Pending:
    pairs_visited: int
    checker_calls: int
    reserved_budget: int


@dataclass(frozen=True)
class _Problem(Generic[Context, Goal]):
    context: Context
    goal: Goal
    alphabet: tuple[Symbol, ...]


class AgreementSearch(Generic[Context, Goal, Proof]):
    """Dovetail candidate index i and checking effort k along i+k diagonals.

    In the unbounded schedule, every (i,k) pair occurs once and receives budget
    k+1. Therefore any permitted finite proof accepted at finite effort is found.
    `advance` is explicitly resource-bounded and returns Pending on interruption.
    It reserves requested budget before each call; it never increases the caller's
    allocation or interprets Pending/Deferred/Rejected as semantic disagreement.

    The checker receives the unchanged context, complete goal and whole term.
    Alphabet indices are meaningful only under this frozen source alphabet.
    """
    __slots__ = ("_problem", "_checker", "diagonal", "position", "terms", "rejected", "found")

    @property
    def context(self) -> Context:
        return self._problem.context

    @property
    def goal(self) -> Goal:
        return self._problem.goal

    @property
    def alphabet(self) -> tuple[Symbol, ...]:
        return self._problem.alphabet

    def __init__(
        self,
        context: Context,
        goal: Goal,
        alphabet: tuple[Symbol, ...],
        checker: Callable[[Context, Goal, tuple[Symbol, ...], Term, int],
                          Accepted[Proof] | Rejected | Deferred],
    ) -> None:
        if not alphabet or len({s.source_id for s in alphabet}) != len(alphabet):
            raise ValueError("the frozen alphabet must be nonempty with unique identities")
        self._problem = _Problem(context, goal, tuple(alphabet))
        self._checker = checker
        self.diagonal = 0
        self.position = 0
        self.terms: dict[int, Term | None] = {}
        self.rejected: dict[int, str] = {}
        self.found: Found[Context, Goal, Proof] | None = None

    def _next_pair(self) -> None:
        self.position += 1
        if self.position > self.diagonal:
            self.diagonal += 1
            self.position = 0

    def advance(self, *, max_pairs: int, budget: int) -> Found[Context, Goal, Proof] | Pending:
        """Advance under explicit limits. An internal checker failure propagates.

        A pair needing more budget is left pending at that exact pair; it is not
        silently skipped or treated as rejected. Calling with further resources
        is an explicit caller action, not an automatic retry of a CAS operation.
        """
        if max_pairs < 0 or budget < 0:
            raise ValueError("limits must be nonnegative")
        if self.found is not None:
            return self.found
        visited = calls = reserved = 0
        while visited < max_pairs:
            i = self.position
            effort = self.diagonal - i + 1
            if i not in self.terms:
                self.terms[i] = decode(code_at(i, len(self.alphabet)), self.alphabet)
            term = self.terms[i]
            if term is None or i in self.rejected:
                self._next_pair()
                visited += 1
                continue
            if effort > budget - reserved:
                break
            # Reservation is conservative: an entire quantum is charged even if
            # the checker finishes early. Production uses its actual global meter.
            reserved += effort
            calls += 1
            result = self._checker(self.context, self.goal, self.alphabet, term, effort)
            if isinstance(result, Accepted):
                self.found = Found(self.context, self.goal, code_at(i, len(self.alphabet)),
                                   term, result.proof)
                return self.found
            if isinstance(result, Rejected):
                self.rejected[i] = result.reason
            elif not isinstance(result, Deferred):
                raise TypeError("the trusted checker returned an invalid checking outcome")
            self._next_pair()
            visited += 1
        return Pending(visited, calls, reserved)

"""Fixed packet peer for categorical source/continuation controls; no mathematics is computed."""

from __future__ import annotations

import json
import sys
from pathlib import Path

from cas_port import input_ref, point_invocation, serve, typed_map
from cas_session import export, proxy

configuration = json.loads(sys.argv[1])
operation = configuration["operation"]
calls = 0


def point_response(arguments):
    global calls
    fields = point_invocation(arguments, operation)
    with Path(configuration["log"]).open("a", encoding="utf-8") as log:
        log.write(json.dumps({"op": operation, "args": arguments}) + "\n")
    calls += 1
    source = proxy(input_ref(["args", 3]))
    target = proxy(input_ref(["args", 5]))
    if configuration["mode"] == "inline":
        if calls == 1:
            assert isinstance(fields[6], dict) and fields[6].get("ctor") == "identity"
            point = configuration["point"]
            body = {"ctor": "finiteGraph", "args": [[point], [[point, point]]]}
            return {"ctor": "typedMap", "args": [
                source.reference(), target.reference(), body,
            ]}
        assert calls == 2
        returned = typed_map(fields[2])
        point = configuration["point"]
        assert returned[2] == {"ctor": "finiteGraph", "args": [[point], [[point, point]]]}
        return proxy(input_ref(["args", 6])).reference()

    assert calls == 1
    retained = []
    capture = configuration.get("capture")
    if capture is not None:
        retained.append(proxy(input_ref(capture)))

    def native_field(context):
        with Path(configuration["log"]).open("a", encoding="utf-8") as log:
            log.write(json.dumps(context) + "\n")
        assert context["kind"] == "dependent"
        assert context["prepared_role"].startswith("project:")
        if retained:
            assert context["prepared_role"].endswith(
                "CategoryTheory.Pseudofunctor.CoGrothendieck.Hom.base"
            )
            return retained[0].reference()

        def native_nested(_context):
            raise NotImplementedError("this fixture exposes only its complete native field")

        return export(native_nested, [])

    body = export(native_field, retained)
    return {"ctor": "typedMap", "args": [source.reference(), target.reference(), body]}


serve("categorical-packet-peer", "0", {operation: point_response})

"""Check complete finite induction covers of an exact source reading grammar.

This is kernel-internal reference code, not a leaf proof interface or a Lean
checker. The fixed problem supplies the exact grammar, source statements and
root judgment BEFORE any candidate is considered. Candidates supply terms only;
they cannot choose the meaning, premises, grammar or requested conclusion.

A successful cover includes every root-reachable production, including cyclic
alternatives, and a checked root implication. Induction on a finite derivation
then establishes the fixed root judgment for every represented route. Checking
an arbitrary finite subset or a pairwise equality cannot create a cover.
"""
from __future__ import annotations

from dataclasses import dataclass
from typing import Callable, Generic, Hashable, TypeVar

from structural_routes_reference import PrefixRule, TraceGrammar, Word, compile_routes

Statement = TypeVar("Statement")
Source = TypeVar("Source")
Evidence = TypeVar("Evidence")
Proof = TypeVar("Proof")
Node = Hashable


@dataclass(frozen=True)
class Rule:
    """One exact production; action retains source occurrences and direction."""
    identity: Hashable
    parent: Node
    children: tuple[Node, ...]
    action: Hashable


@dataclass(frozen=True)
class RuleGoal(Generic[Statement]):
    rule: Rule
    premises: tuple[Statement, ...]
    conclusion: Statement


@dataclass(frozen=True)
class RootGoal(Generic[Statement]):
    premise: Statement
    conclusion: Statement


@dataclass(frozen=True)
class Checked(Generic[Proof]):
    """A term accepted at the exact requested goal by the internal checker."""
    proof: Proof


@dataclass(frozen=True)
class Invalid:
    """This cover/candidate is invalid; the mathematical query is not refuted."""
    reason: str


@dataclass(frozen=True)
class Pending:
    """No coverage judgment; includes incomplete evidence or resource limits."""
    reason: str


@dataclass(frozen=True)
class Candidate(Generic[Evidence]):
    # Only proof terms: no candidate-supplied source, goal or invariant fields.
    rules: tuple[tuple[Hashable, Evidence], ...]
    root: Evidence


@dataclass(frozen=True)
class FixedProblem(Generic[Source, Statement]):
    """Prepared privately from the accepted source and exact reading grammar.

    Source/Statement objects must themselves be immutable (native production
    uses the persistent Lean environment, closed expressions and rigid context).
    Arbitrary caller-selected predicates are not an interpretation authority.
    """
    source: Source
    start: Node
    rules: tuple[Rule, ...]
    statements: tuple[tuple[Node, Statement], ...]
    goal: Statement
    route_binding: tuple[tuple[PrefixRule, ...], Word, frozenset[Word]] | None = None

    def __post_init__(self) -> None:
        ids = [r.identity for r in self.rules]
        nodes = [n for n, _ in self.statements]
        if len(ids) != len(set(ids)) or len(nodes) != len(set(nodes)):
            raise ValueError("duplicate production identity or statement owner")
        known = set(nodes)
        if self.start not in known:
            raise ValueError("start has no fixed statement")
        if any(r.parent not in known or any(c not in known for c in r.children)
               for r in self.rules):
            raise ValueError("production mentions an undeclared nonterminal")

    def obligations(self) -> tuple[RuleGoal[Statement], ...]:
        # Reachability is syntactic and exhaustive; no candidate or checker
        # participates in deciding which production alternatives are retained.
        reachable = {self.start}
        changed = True
        while changed:
            changed = False
            for rule in self.rules:
                if rule.parent in reachable:
                    old = len(reachable)
                    reachable.update(rule.children)
                    changed |= len(reachable) != old
        statements = dict(self.statements)
        return tuple(RuleGoal(rule, tuple(statements[c] for c in rule.children),
                              statements[rule.parent])
                     for rule in self.rules if rule.parent in reachable)


def from_trace_grammar(
    source: Source,
    grammar: TraceGrammar,
    statements: tuple[tuple[Node, Statement], ...],
    goal: Statement,
) -> FixedProblem[Source, Statement]:
    """Snapshot the complete compiler-produced grammar, never a candidate view.

    Each production identity contains its parent and the complete production,
    not just the emitted edge label. The snapshot retains recursive alternatives
    and is unaffected by later mutation of the reference grammar's dictionary.
    Source statements must name every and only the actual grammar nonterminals.
    """
    nodes = [node for node, _ in statements]
    if len(nodes) != len(set(nodes)) or set(nodes) != set(grammar.productions):
        raise ValueError("statement owners differ from the exact grammar")
    rules = tuple(Rule((parent, production), parent, production.children,
                       production.emit)
                  for parent, productions in grammar.productions.items()
                  for production in productions)
    return FixedProblem(source, grammar.start, rules, statements, goal)


@dataclass(frozen=True)
class CompleteCover(Generic[Source, Statement, Proof]):
    problem: FixedProblem[Source, Statement]
    obligations: tuple[RuleGoal[Statement], ...]
    rule_proofs: tuple[Proof, ...]
    root_goal: RootGoal[Statement]
    root_proof: Proof


def check_cover(
    problem: FixedProblem[Source, Statement],
    candidate: Candidate[Evidence],
    check: Callable[[Source, RuleGoal[Statement] | RootGoal[Statement], Evidence, int],
                    Checked[Proof] | Invalid | Pending],
    *,
    budget: int,
    quantum: int = 1,
    efforts: tuple[int, ...] | None = None,
) -> CompleteCover[Source, Statement, Proof] | Invalid | Pending:
    """Verify every exact local implication and the requested root judgment.

    This reference conservatively reserves a quantum per checker invocation.
    The checker must meter generation and checking within that quantum. Runtime
    errors propagate; neither budget exhaustion nor a failed candidate is a
    semantic negative. Fair search over candidates/efforts is a separate owner.
    """
    if budget < 0 or quantum <= 0:
        raise ValueError("budget must be nonnegative and quantum positive")
    obligations = problem.obligations()
    ids = [identity for identity, _ in candidate.rules]
    if len(ids) != len(set(ids)):
        return Invalid("duplicate evidence for a production")
    expected = {goal.rule.identity for goal in obligations}
    provided = set(ids)
    if provided - expected:
        return Invalid("evidence names a production outside the exact root grammar")
    if expected - provided:
        return Pending("evidence does not cover every root-reachable production")
    root = RootGoal(dict(problem.statements)[problem.start], problem.goal)
    quanta = efforts if efforts is not None else (quantum,) * (len(obligations) + 1)
    if len(quanta) != len(obligations) + 1 or any(q <= 0 for q in quanta):
        raise ValueError("efforts must give a positive budget for every exact obligation")
    evidence = dict(candidate.rules)
    proofs: list[Proof] = []
    for goal, effort in zip((*obligations, root), quanta):
        if budget < effort:
            return Pending("coverage checking resource exhausted")
        budget -= effort
        term = candidate.root if isinstance(goal, RootGoal) else evidence[goal.rule.identity]
        result = check(problem.source, goal, term, effort)
        if isinstance(result, (Invalid, Pending)):
            return result
        if not isinstance(result, Checked):
            raise TypeError("the source checker returned an invalid outcome")
        proofs.append(result.proof)
    return CompleteCover(problem, obligations, tuple(proofs[:-1]), root, proofs[-1])


@dataclass(frozen=True)
class SelectionGoal:
    """The full source judgment and comparison program are fixed, not inferred
    from this route's endpoints or from a proof search's enumeration order.
    Native production fields are closed typed Lean expressions with full context.
    """
    route: Word
    judgment: Hashable
    comparison_program: Hashable


@dataclass(frozen=True)
class Selected(Generic[Source, Statement, Proof]):
    cover: CompleteCover[Source, Statement, Proof]
    goal: SelectionGoal
    occurrences: tuple


def prepare_selection(
    source: Source,
    rules: tuple[PrefixRule, ...],
    initial: Word,
    targets: frozenset[Word],
    statements: tuple[tuple[Node, Statement], ...],
    goal: SelectionGoal,
) -> FixedProblem:
    """Prepare from the original rule table; a caller cannot prune the grammar.

    A route is checked before coverage. In particular, a vacuous cover of an
    empty reading language cannot authorize execution of a nonexistent reading.
    This preparation does not assert mathematical agreement or pick a provider.
    """
    language = compile_routes(rules, initial, targets)
    language.reconstruct(goal.route)
    base = from_trace_grammar(source, language.grammar, statements, goal)
    return FixedProblem(base.source, base.start, base.rules, base.statements,
                        base.goal, (tuple(rules), tuple(initial), frozenset(targets)))


def authorize_selection(cover: CompleteCover) -> Selected | Invalid:
    """Require the exact checked coverage and a real member, not a raw count.

    The reference rechecks structural preparation against the original table.
    Native production retains the checked immutable preparation instead. Neither
    implementation calls a provider to determine mathematical selection.
    """
    p = cover.problem
    if not isinstance(p.goal, SelectionGoal) or p.route_binding is None:
        return Invalid("a generic coverage theorem is not a prepared selection")
    rules, initial, targets = p.route_binding
    language = compile_routes(rules, initial, targets)
    exact = from_trace_grammar(p.source, language.grammar, p.statements, p.goal)
    if p.start != exact.start or frozenset(p.rules) != frozenset(exact.rules):
        return Invalid("coverage used a different or pruned grammar")
    if cover.obligations != p.obligations() or len(cover.rule_proofs) != len(cover.obligations):
        return Invalid("checked coverage does not contain every prepared obligation")
    if cover.root_goal != RootGoal(dict(p.statements)[p.start], p.goal):
        return Invalid("checked root is not the complete fixed selection goal")
    try:
        occurrences = language.reconstruct(p.goal.route)
    except ValueError as error:
        return Invalid(str(error))
    return Selected(cover, p.goal, occurrences)

"""Executable countermodel for G1's proposed total agreement classifier.

This is an engineering model, not the production resolver or a new acceptance
oracle. The proof and exact categorical interpretation are in issue #66.
Every selected finite route terminates; deciding agreement of *all* routes is
not implemented or claimed. No sampled prefix is called a uniqueness proof.
"""
from __future__ import annotations

from dataclasses import dataclass
from itertools import product
from typing import Callable, Iterable


@dataclass(frozen=True)
class Instruction:
    next_state: int
    write: int
    move: int

    def __post_init__(self) -> None:
        if self.next_state < 0 or self.write not in (0, 1) or self.move not in (-1, 0, 1):
            raise ValueError("invalid binary-tape instruction")


@dataclass(frozen=True)
class Machine:
    """A deterministic binary-tape machine; absent transitions halt.

    Rows are (state, scanned symbol, instruction). Duplicate keys are rejected.
    The blank input has state 0, head 0 and an all-zero two-sided tape.
    """
    rows: tuple[tuple[int, int, Instruction], ...]

    def __post_init__(self) -> None:
        keys = [(q, a) for q, a, _ in self.rows]
        if any(q < 0 or a not in (0, 1) for q, a in keys):
            raise ValueError("invalid transition key")
        if len(keys) != len(set(keys)):
            raise ValueError("duplicate transition key")

    def halts_within(self, steps: int) -> bool:
        """Decide only bounded halting, by an explicitly finite simulation."""
        if steps < 0:
            raise ValueError("steps must be nonnegative")
        transitions = {(q, a): instruction for q, a, instruction in self.rows}
        ones: set[int] = set()
        state = head = 0
        for elapsed in range(steps + 1):
            instruction = transitions.get((state, int(head in ones)))
            if instruction is None:
                return True
            if elapsed == steps:
                return False
            if instruction.write:
                ones.add(head)
            else:
                ones.discard(head)
            state, head = instruction.next_state, head + instruction.move
        raise AssertionError("finite simulation fell through")

    def marked_bit(self, n: int) -> int:
        """s_M(0)=0; s_M(n+1)=1 iff M halts in at most n transitions."""
        if n < 0:
            raise ValueError("route index must be nonnegative")
        return int(n > 0 and self.halts_within(n - 1))


@dataclass(frozen=True)
class Tower:
    """A set with two fixed points and a countable family of selected points."""
    carrier: tuple[int, ...]
    zero: int
    one: int
    points: Callable[[int], int]

    def tail(self) -> Tower:
        return Tower(self.carrier, self.zero, self.one, lambda n: self.points(n + 1))

    def head(self) -> tuple[tuple[int, ...], int, int, int]:
        return (self.carrier, self.zero, self.one, self.points(0))


def machine_tower(machine: Machine) -> Tower:
    return Tower((0, 1), 0, 1, machine.marked_bit)


@dataclass(frozen=True)
class SelectedRoute:
    """The exact first-hit route enter; tail^n; head; origin remains retained."""
    tail_count: int

    def __post_init__(self) -> None:
        if self.tail_count < 0:
            raise ValueError("tail_count must be nonnegative")

    @property
    def labels(self) -> tuple[str, ...]:
        return ("enter",) + ("tail",) * self.tail_count + ("head",)

    def whole_family(self, machine: Machine) -> tuple[int]:
        """Exact table of Unit -> Bool, not a sample of an infinite domain.

        The rigid source object ranges over the one-object classifier total;
        the nullary operand ranges over Unit. Both variables remain arbitrary.
        """
        return (machine.marked_bit(self.tail_count),)


def accepts_first_hit(labels: Iterable[str]) -> bool:
    """Finite automaton for enter . tail* . head; target is absorbing."""
    state = "source"
    for label in labels:
        if state == "source" and label == "enter":
            state = "tower"
        elif state == "tower" and label == "tail":
            pass
        elif state == "tower" and label == "head":
            state = "owner"
        else:
            return False
    return state == "owner"


@dataclass(frozen=True)
class DifferenceWitness:
    left: SelectedRoute
    right: SelectedRoute
    left_family: tuple[int]
    right_family: tuple[int]


@dataclass(frozen=True)
class Undetermined:
    checked_through: int


def inspect_prefix(machine: Machine, through: int) -> DifferenceWitness | Undetermined:
    """A finite diagnostic: never infer global agreement from a quiet prefix."""
    if through < 0:
        raise ValueError("through must be nonnegative")
    initial = SelectedRoute(0)
    for n in range(1, through + 1):
        route = SelectedRoute(n)
        if route.whole_family(machine) != initial.whole_family(machine):
            return DifferenceWitness(initial, route, initial.whole_family(machine), route.whole_family(machine))
    return Undetermined(through)


def halt_after(steps: int) -> Machine:
    """An explicit finite machine halting after exactly `steps` transitions."""
    if steps < 0:
        raise ValueError("steps must be nonnegative")
    return Machine(tuple((q, a, Instruction(q + 1, a, 0)) for q in range(steps) for a in (0, 1)))


def loop_forever() -> Machine:
    return Machine(((0, 0, Instruction(0, 0, 0)), (0, 1, Instruction(0, 1, 0))))


def all_binary_maps() -> tuple[tuple[int, int], ...]:
    return tuple(product((0, 1), repeat=2))


def apply_map(mapping: tuple[int, int], value: int) -> int:
    return mapping[value]


def preserves_base_points(mapping: tuple[int, int]) -> bool:
    return apply_map(mapping, 0) == 0 and apply_map(mapping, 1) == 1

"""Protocol-only traffic through the unchanged pinned v1 SDK."""

from __future__ import annotations

import json
import os
from pathlib import Path
import sys
from collections.abc import Callable

import cas_port

type JsonValue = None | bool | int | float | str | list[JsonValue] | dict[str, JsonValue]

record = Path(sys.argv[1])
with record.open("a") as output:
    output.write(str(os.getpid()) + "\n")
values: dict[str, JsonValue] = {}


def echo(arguments: JsonValue) -> JsonValue:
    return arguments


def state(arguments: JsonValue) -> JsonValue:
    return {"pid": os.getpid(), "cwd": os.getcwd(), "helper": cas_port.__file__,
            "contract": os.environ["CAS_LEAF_CONTRACT_PATH"],
            "probe": os.environ["CAS_BRIDGE_PROBE"], "arguments": arguments}


def retain(arguments: JsonValue) -> JsonValue:
    token = f"original-{len(values)}"
    values[token] = arguments
    return cas_port.opaque_data(token)


def invoke(arguments: JsonValue) -> JsonValue:
    fields = cas_port.point_invocation(arguments, "traffic.invoke")
    _, _, callable_data = cas_port.typed_map(fields[2])
    token = callable_data["args"][0]
    return {"retained": values[token], "context": json.dumps(fields, ensure_ascii=False)}


def fail(arguments: JsonValue) -> JsonValue:
    raise ArithmeticError("original computational failure")


def deferred(arguments: JsonValue) -> JsonValue:
    return cas_port.deferred_data([
        cas_port.deferred_call("traffic.echo", "traffic#input", cas_port.input_ref(["payload"]))
    ], cas_port.result_ref(0))


def observed(operation: str, handler: Callable[[JsonValue], JsonValue]) -> Callable[[JsonValue], JsonValue]:
    def invoke(arguments: JsonValue) -> JsonValue:
        with record.with_suffix(".calls").open("a") as output:
            output.write(json.dumps({"op": operation, "args": arguments}) + "\n")
        return handler(arguments)
    return invoke


cas_port.serve("original-traffic", "0", "pinned-v1", {
    operation: observed(operation, handler) for operation, handler in {
        "traffic.echo": echo, "traffic.state": state, "traffic.retain": retain,
        "traffic.invoke": invoke, "traffic.fail": fail, "traffic.deferred": deferred,
    }.items()
}, protocol=2 if len(sys.argv) > 2 and sys.argv[2] == "wrong-protocol" else 1)

"""Protocol traffic peer. It supplies no mathematical computation."""

from __future__ import annotations

from collections.abc import Generator
import json
import sys

from cas_session import JsonValue, Proxy, Suspension, export, invoke_routine, proxy, suspend
from cas_port import serve


def echo(arguments: JsonValue) -> JsonValue:
    return arguments


def delegated(arguments: JsonValue) -> JsonValue:
    return invoke_routine(echo, arguments)


def stored(arguments: JsonValue) -> JsonValue:
    def invoke(context: JsonValue) -> JsonValue:
        from cas_port import input_ref

        assert isinstance(context, dict)
        result: dict[str, JsonValue] = {
            "stored": arguments, "context": json.dumps(context, ensure_ascii=False)
        }
        if context.get("kind") == "dependent":
            values = context["arguments"]
            assert isinstance(values, list)
            if values:
                result["argument"] = proxy(input_ref(["arguments", 0])).reference()
        return result

    return export(invoke, [])


def captured(arguments: JsonValue) -> JsonValue:
    from cas_port import input_ref
    from contextvars import copy_context

    first = proxy(input_ref(["first"]))
    second = proxy(input_ref(["second"]))
    unretained = proxy(input_ref(["unretained"]))
    previous = copy_context()

    def invoke(context: JsonValue) -> JsonValue:
        nonlocal previous
        for read in [lambda: previous.run(first.reference), unretained.reference]:
            try:
                read()
            except ValueError:
                pass
            else:
                raise ValueError("a prior frame or undeclared capture retained authority")
        previous = copy_context()
        assert isinstance(context, dict)
        arguments = context["arguments"]
        assert isinstance(arguments, list)
        return [second.reference(), first.reference(), proxy(arguments[0]).reference()]

    return export(invoke, [first, second])


saved: Proxy | None = None


def adaptive(arguments: JsonValue) -> Generator[Suspension, list[Proxy], JsonValue]:
    global saved
    assert isinstance(arguments, dict)
    original = proxy(arguments["value"])
    saved = original
    results = yield suspend([original.project(0)], [original])
    return {"original": original.reference(), "child": results[0].reference()}


def expired(arguments: JsonValue) -> JsonValue:
    assert saved is not None
    return saved.reference()


category_saved = None


def category_result(arguments: JsonValue):
    """Use generated family metadata with actual SDK gateway occurrences."""
    from cas_port import load_interfaces

    global category_saved
    assert isinstance(arguments, dict)
    family = load_interfaces(sys.argv[2]).category("cat.groups").family(
        "morphism", "mor.groups.trivial")
    original = family.result(proxy(arguments["value"]))
    category_saved = original
    children = yield suspend([original.project(0)], [original.value])
    return {"original": original.reference(), "child": children[0].reference()}


def category_expired(arguments: JsonValue):
    assert category_saved is not None
    return category_saved.project(0)


def references(arguments: JsonValue) -> JsonValue:
    assert isinstance(arguments, dict)
    from cas_port import input_ref

    return proxy(input_ref(["item"])).reference()


def deferred(arguments: JsonValue) -> JsonValue:
    from cas_port import deferred_data, result_ref

    value = proxy(arguments)
    return deferred_data([value.project(0), {"op": "$cas.apply", "args": {
        "value": result_ref(0), "arguments": []}}], result_ref(1))


def hidden(arguments: JsonValue) -> Generator[Suspension, list[Proxy], JsonValue]:
    value = proxy(arguments)
    yield suspend([value.project(0)], [])
    return value.reference()


def repeated(arguments: JsonValue) -> Generator[Suspension, list[Proxy], JsonValue]:
    assert isinstance(arguments, list)
    first, second = [proxy(value) for value in arguments]
    result = yield suspend([first.project(0)], [first, second])
    result = yield suspend([result[0].apply([second.reference()])], [second, result[0], first])
    return [first.reference(), second.reference(), result[0].reference()]


serve("protocol-peer", "0", {"echo": echo, "delegated": delegated, "stored": stored,
                              "captured": captured,
                              "adaptive": adaptive, "expired": expired,
                              "references": references, "deferred": deferred,
                              "hidden": hidden, "repeated": repeated,
                              **({"category_result": category_result,
                                  "category_expired": category_expired}
                                 if len(sys.argv) == 3 and sys.argv[1] == "--category-interface"
                                 else {}),
                              # An opt-in fixed packet tests property observation framing only.
                              # It never inspects a group or computes a property.
                              **({"prop.is_abelian": lambda _arguments: json.loads(sys.argv[2])}
                                 if len(sys.argv) == 3 and sys.argv[1] == "--property-observation"
                                 else {})})

"""Fixed complete-cone packets for the original native constructor controls."""

from __future__ import annotations

import json
import sys
from pathlib import Path

from cas_port import input_ref, serve
from cas_session import export, proxy


configuration = json.loads(sys.argv[1])
operation = "lim.sets.product"
apex = {"ctor": "finiteData", "args": ["original-product", [[0, 0]]]}


def construction(arguments):
    assert arguments["ctor"] == "pair"
    assert len(arguments["args"]) == 2
    with Path(configuration["log"]).open("a", encoding="utf-8") as log:
        log.write(json.dumps({"op": operation, "args": arguments}) + "\n")
    endpoints = [proxy(input_ref(["args", index])) for index in range(2)]

    def native_map(_context):
        raise NotImplementedError("this fixture returns the complete native map only")

    if configuration["mode"] == "opaque":
        return export(native_map, endpoints)
    maps = []
    for index in range(2):
        target = endpoints[1 - index] if configuration["mode"] == "swapped" else endpoints[index]
        if configuration["mode"] in {"owned", "wrapped-owned"}:
            body = export(native_map, [target])
        else:
            body = {"ctor": "finiteGraph", "args": [[[0, 0]], [[[0, 0], 0]]]}
        maps.append(body if configuration["mode"] == "bare" else
                    {"ctor": "typedMap", "args": [apex, target.reference(), body]})
    fields = [apex, *maps]
    if configuration["mode"] == "missing":
        fields.pop()
    result = {"ctor": "cone", "args": fields}
    if configuration["mode"].startswith("wrapped"):
        result = {"ctor": "valueData", "args": [{"ctor": "valueData", "args": [result]}]}
    return result


serve("raw-construction-peer", "0", {operation: construction})

"""Exact first-hit route languages for finite ground-prefix structural rules.

Engineering reference for the source correspondence documented in issue #66.
It decides structural reachability and represents *all* finite first-hit traces.
It neither identifies mathematical meanings nor accepts provider proof data.

A rule lhs -> rhs applies at a word prefix. Words encode an entire residual
category atom followed by its inner-to-outer unary constructor context. The
production adapter must retain exact source identities, parameters and roles.
Strings below are model symbols, not names from which semantics are inferred.

Construction: annotate the pushdown stack by a bottom-up target DFA, make target
configurations absorbing, and compute productive empty-stack summaries. Keep
all productive grammar alternatives, not only first-discovery witnesses.
The algorithms have no route/stack depth cutoff. Resource exhaustion must not
be translated into mathematical absence or ambiguity by a production caller.
"""
from __future__ import annotations

from collections import defaultdict
from dataclasses import dataclass
from typing import Callable, Hashable, Iterable

Word = tuple[str, ...]
State = int
Symbol = Hashable
Summary = tuple[State, Symbol, State]


@dataclass(frozen=True)
class PrefixRule:
    name: str
    lhs: Word
    rhs: Word

    def __post_init__(self) -> None:
        if not self.name or not self.lhs or not self.rhs:
            raise ValueError("source rules require an identity and nonempty endpoints")
        if not all(isinstance(x, str) and x for x in self.lhs + self.rhs):
            raise ValueError("source symbols must be nonempty strings")


@dataclass(frozen=True)
class Transition:
    source: State
    pop: Symbol
    target: State
    push: tuple[Symbol, ...]
    emit: str | None = None


@dataclass(frozen=True)
class Production:
    """A source trace symbol, possibly epsilon, followed by child summaries."""
    emit: str | None
    children: tuple[Summary, ...]


@dataclass
class TraceGrammar:
    start: Summary
    productions: dict[Summary, frozenset[Production]]

    def shortest(self) -> Word | None:
        """Least trace in shortlex order, or None iff the language is empty."""
        best: dict[Summary, Word] = {}
        changed = True
        while changed:
            changed = False
            for lhs, alternatives in self.productions.items():
                for alternative in alternatives:
                    if not all(child in best for child in alternative.children):
                        continue
                    word = (() if alternative.emit is None else (alternative.emit,))
                    word += tuple(x for child in alternative.children for x in best[child])
                    old = best.get(lhs)
                    if old is None or (len(word), word) < (len(old), old):
                        best[lhs] = word
                        changed = True
        return best.get(self.start)

    def intersects_dfa(
        self,
        states: tuple[int, ...],
        initial: int,
        accepting: frozenset[int],
        step: Callable[[int, str], int],
    ) -> bool:
        """Exact CFL/regular intersection emptiness via finite relations.

        For each nonterminal N, R_N(p,q) means some N-word takes DFA p to q.
        Production interpretation is relational composition, iterated to its
        least fixed point. No generation or sampling of grammar words occurs.
        """
        state_set = frozenset(states)
        if len(state_set) != len(states) or initial not in state_set or not accepting <= state_set:
            raise ValueError("invalid finite automaton state set")
        alphabet = {a.emit for alternatives in self.productions.values() for a in alternatives if a.emit is not None}
        moves = {(p, a): step(p, a) for p in states for a in alphabet}
        if not all(q in state_set for q in moves.values()):
            raise ValueError("DFA transition leaves its state set")
        relations = {nt: set() for nt in self.productions}
        changed = True
        while changed:
            changed = False
            for lhs, alternatives in self.productions.items():
                for alternative in alternatives:
                    edges = {(p, p) for p in states} if alternative.emit is None else {(p, moves[p, alternative.emit]) for p in states}
                    for child in alternative.children:
                        rhs = relations.get(child, set())
                        edges = {(p, r) for p, q in edges for q2, r in rhs if q == q2}
                        if not edges:
                            break
                    before = len(relations[lhs])
                    relations[lhs].update(edges)
                    changed |= len(relations[lhs]) != before
        return any(p == initial and q in accepting for p, q in relations.get(self.start, set()))

    def contains(self, word: Word) -> bool:
        dead = len(word) + 1
        states = tuple(range(dead + 1))
        def step(position: int, letter: str) -> int:
            return position + 1 if position < len(word) and word[position] == letter else dead
        return self.intersects_dfa(states, 0, frozenset({len(word)}), step)

    def finite_words(self) -> frozenset[Word] | None:
        """Enumerate the exact raw language if finite; None means infinite.

        A productive dependency cycle is length-growing exactly when some
        edge has a terminal or a nonempty sibling derivation in its context.
        Silent recursive parses alone do not imply infinitely many words.
        """
        productive: set[Summary] = set()
        nonempty: set[Summary] = set()
        changed = True
        while changed:
            changed = False
            for lhs, alternatives in self.productions.items():
                for alternative in alternatives:
                    if all(child in productive for child in alternative.children):
                        if lhs not in productive:
                            productive.add(lhs)
                            changed = True
                        if (alternative.emit is not None or any(child in nonempty for child in alternative.children)) and lhs not in nonempty:
                            nonempty.add(lhs)
                            changed = True
        graph: dict[Summary, set[Summary]] = defaultdict(set)
        growing = []
        for lhs, alternatives in self.productions.items():
            for alternative in alternatives:
                if not all(child in productive for child in alternative.children):
                    continue
                for i, child in enumerate(alternative.children):
                    graph[lhs].add(child)
                    if alternative.emit is not None or any(other in nonempty for j, other in enumerate(alternative.children) if i != j):
                        growing.append((lhs, child))
        def reachable(source: Summary) -> set[Summary]:
            seen = {source}
            work = [source]
            while work:
                for target in graph.get(work.pop(), ()):
                    if target not in seen:
                        seen.add(target)
                        work.append(target)
            return seen
        live = reachable(self.start)
        for source, target in growing:
            if source in live and source in reachable(target):
                return None
        # Absence of a growing cycle proves that this monotone finite-language
        # fixed point terminates. Do not truncate its words or derivations.
        languages: dict[Summary, set[Word]] = {nt: set() for nt in live}
        changed = True
        while changed:
            changed = False
            for lhs in live:
                for alternative in self.productions.get(lhs, ()):
                    if not all(child in productive for child in alternative.children):
                        continue
                    words = {() if alternative.emit is None else (alternative.emit,)}
                    for child in alternative.children:
                        words = {prefix + suffix for prefix in words for suffix in languages[child]}
                    before = len(languages[lhs])
                    languages[lhs].update(words)
                    changed |= len(languages[lhs]) != before
        return frozenset(languages.get(self.start, set()))

    def distinct_word_count(self) -> int:
        """0, 1 or 2 (meaning >=2) *raw traces*, never semantic meanings."""
        witness = self.shortest()
        if witness is None:
            return 0
        dead = len(witness) + 1
        states = tuple(range(dead + 1))
        def step(position: int, letter: str) -> int:
            return position + 1 if position < len(witness) and witness[position] == letter else dead
        accepts_other = frozenset(p for p in states if p != len(witness))
        return 2 if self.intersects_dfa(states, 0, accepts_other, step) else 1


@dataclass(frozen=True)
class RouteOccurrence:
    rule: str
    source: Word
    target: Word
    outer_context: Word


@dataclass
class RouteLanguage:
    rules: tuple[PrefixRule, ...]
    initial: Word
    targets: frozenset[Word]
    grammar: TraceGrammar
    controls: int
    transition_count: int

    def reconstruct(self, trace: Word) -> tuple[RouteOccurrence, ...]:
        """Reconstruct formal source occurrences, never lost runtime values."""
        by_name = {rule.name: rule for rule in self.rules}
        at = self.initial
        out = []
        for name in trace:
            if at in self.targets:
                raise ValueError("route continues after a first binding")
            rule = by_name.get(name)
            if rule is None or at[:len(rule.lhs)] != rule.lhs:
                raise ValueError("trace is not a composable source derivation")
            context = at[len(rule.lhs):]
            target = rule.rhs + context
            out.append(RouteOccurrence(name, at, target, context))
            at = target
        if at not in self.targets:
            raise ValueError("route does not reach an owner/binding")
        return tuple(out)


class _TargetDFA:
    def __init__(self, targets: frozenset[tuple[Symbol, ...]]):
        reversed_targets = {tuple(reversed(word)) for word in targets}
        prefixes = {()}
        for word in reversed_targets:
            prefixes.update(word[:i] for i in range(len(word) + 1))
        # Ordering affects only internal identity, never route choice.
        self.prefixes = sorted(prefixes, key=lambda p: (len(p), repr(p)))
        self.index = {p: i for i, p in enumerate(self.prefixes)}
        self.dead = len(self.prefixes)
        self.states = tuple(range(self.dead + 1))
        self.initial = self.index[()]
        self.accepting = frozenset(self.index[word] for word in reversed_targets)

    def step(self, state: int, letter: Symbol) -> int:
        if state == self.dead:
            return self.dead
        return self.index.get(self.prefixes[state] + (letter,), self.dead)


def _productive_grammar(transitions: tuple[Transition, ...], start: Summary) -> TraceGrammar:
    """All productive PDA-to-CFG productions, with push words of length <=2."""
    finishes: dict[tuple[State, Symbol], set[State]] = defaultdict(set)
    changed = True
    while changed:
        changed = False
        for rule in transitions:
            if not rule.push:
                ends = {rule.target}
            elif len(rule.push) == 1:
                ends = set(finishes[rule.target, rule.push[0]])
            else:
                ends = {end for middle in tuple(finishes[rule.target, rule.push[0]]) for end in tuple(finishes[middle, rule.push[1]])}
            destination = finishes[rule.source, rule.pop]
            before = len(destination)
            destination.update(ends)
            changed |= len(destination) != before
    alternatives: dict[Summary, set[Production]] = defaultdict(set)
    for rule in transitions:
        if not rule.push:
            alternatives[rule.source, rule.pop, rule.target].add(Production(rule.emit, ()))
        elif len(rule.push) == 1:
            for end in finishes[rule.target, rule.push[0]]:
                alternatives[rule.source, rule.pop, end].add(Production(rule.emit, ((rule.target, rule.push[0], end),)))
        else:
            first, second = rule.push
            for middle in finishes[rule.target, first]:
                for end in finishes[middle, second]:
                    alternatives[rule.source, rule.pop, end].add(Production(rule.emit, ((rule.target, first, middle), (middle, second, end))))
    # Remove unreachable grammar nodes, but never an alternative of a reachable one.
    reached = {start}
    work = [start]
    while work:
        for alternative in alternatives.get(work.pop(), ()):
            for child in alternative.children:
                if child not in reached:
                    reached.add(child)
                    work.append(child)
    return TraceGrammar(start, {nt: frozenset(alternatives.get(nt, ())) for nt in reached})


def compile_routes(rules: Iterable[PrefixRule], initial: Word, targets: Iterable[Word]) -> RouteLanguage:
    """Compile the exact complete first-hit relation to a finite trace grammar."""
    rules = tuple(rules)
    targets = frozenset(tuple(word) for word in targets)
    if not initial or any(not word for word in targets):
        raise ValueError("source category words must be nonempty")
    if len({rule.name for rule in rules}) != len(rules):
        raise ValueError("source rule identities must be unique")
    words = (initial, *targets, *(word for rule in rules for word in (rule.lhs, rule.rhs)))
    if not all(isinstance(x, str) and x for word in words for x in word):
        raise ValueError("source symbols must be nonempty strings")
    bottom: Symbol = ("private", "bottom")
    start_symbol: Symbol = ("private", "start")
    source_alphabet: tuple[Symbol, ...] = tuple(sorted({x for word in words for x in word})) + (bottom,)
    dfa = _TargetDFA(frozenset(word + (bottom,) for word in targets))
    annotated = tuple((letter, summary) for letter in source_alphabet for summary in dfa.states)

    def annotate(word: tuple[Symbol, ...], below: int) -> tuple[Symbol, ...]:
        reversed_out = []
        state = below
        for letter in reversed(word):
            reversed_out.append((letter, state))
            state = dfa.step(state, letter)
        return tuple(reversed(reversed_out))

    normal, drain, final, init = 0, 1, 2, 3
    next_state = 4
    transitions: list[Transition] = []

    def fresh() -> int:
        nonlocal next_state
        state = next_state
        next_state += 1
        return state

    def emit_push(source: int, pop: Symbol, target: int, push: tuple[Symbol, ...], emit: str | None) -> None:
        # Normalize a long push through private controls; all intermediate
        # transitions are silent and cannot start another source rule or accept.
        if len(push) <= 2:
            transitions.append(Transition(source, pop, target, push, emit))
            return
        control = fresh()
        transitions.append(Transition(source, pop, control, push[-2:], emit))
        for i in range(len(push) - 3, -1, -1):
            following = target if i == 0 else fresh()
            transitions.append(Transition(control, push[i + 1], following, (push[i], push[i + 1]), None))
            control = following

    for rule in rules:
        matching = [normal] + [fresh() for _ in rule.lhs[1:]]
        for i, expected in enumerate(rule.lhs):
            for summary in dfa.states:
                if i == 0 and dfa.step(summary, expected) in dfa.accepting:
                    continue
                top: Symbol = (expected, summary)
                if i + 1 < len(rule.lhs):
                    transitions.append(Transition(matching[i], top, matching[i + 1], (), None))
                else:
                    emit_push(matching[i], top, normal, annotate(rule.rhs, summary), rule.name)
    for top in annotated:
        letter, summary = top
        if letter == bottom:
            transitions.append(Transition(drain, top, final, (), None))
        else:
            transitions.append(Transition(drain, top, drain, (), None))
            if dfa.step(summary, letter) in dfa.accepting:
                transitions.append(Transition(normal, top, drain, (), None))
    emit_push(init, start_symbol, normal, annotate(initial + (bottom,), dfa.initial), None)
    unique_transitions = tuple(dict.fromkeys(transitions))
    start = (init, start_symbol, final)
    grammar = _productive_grammar(unique_transitions, start)
    return RouteLanguage(rules, initial, targets, grammar, next_state, len(unique_transitions))

"""Checks of the G1 countermodel; not evidence of a total agreement solver."""
import itertools
import unittest

from g1_agreement_countermodel import (
    DifferenceWitness, Instruction, Machine, SelectedRoute, Tower, Undetermined,
    accepts_first_hit, all_binary_maps, halt_after, inspect_prefix,
    loop_forever, machine_tower, preserves_base_points,
)


class CountermodelTests(unittest.TestCase):
    def test_exact_first_hit_language(self):
        for length in range(9):
            for word in itertools.product(("enter", "tail", "head"), repeat=length):
                expected = length >= 2 and word[0] == "enter" and word[-1] == "head" and all(x == "tail" for x in word[1:-1])
                with self.subTest(word=word):
                    self.assertEqual(accepts_first_hit(word), expected)

    def test_every_selected_route_is_retained(self):
        for n in range(100):
            self.assertTrue(accepts_first_hit(SelectedRoute(n).labels))
            self.assertEqual(SelectedRoute(n).labels.count("tail"), n)
        self.assertNotEqual(SelectedRoute(1), SelectedRoute(2))

    def test_halting_boundary_and_whole_families(self):
        for halt in range(65):
            machine = halt_after(halt)
            for n in range(67):
                with self.subTest(halt=halt, n=n):
                    expected = int(n >= halt + 1)
                    self.assertEqual(machine.marked_bit(n), expected)
                    self.assertEqual(SelectedRoute(n).whole_family(machine), (expected,))

    def test_no_finite_prefix_proves_agreement(self):
        for bound in range(65):
            machine = halt_after(bound + 1)
            self.assertIsInstance(inspect_prefix(machine, bound), Undetermined)
            witness = inspect_prefix(machine, bound + 2)
            self.assertIsInstance(witness, DifferenceWitness)
            self.assertEqual(witness.left_family, (0,))
            self.assertEqual(witness.right_family, (1,))

    def test_nonhalting_prefix_is_not_mislabelled(self):
        machine = loop_forever()
        for n in range(100):
            self.assertEqual(machine.marked_bit(n), 0)
        self.assertEqual(inspect_prefix(machine, 100), Undetermined(100))

    def test_forgetting_retains_carrier_and_base_points(self):
        for n in range(20):
            tower = machine_tower(halt_after(7))
            for _ in range(n):
                tower = tower.tail()
            self.assertEqual(tower.head(), ((0, 1), 0, 1, int(n >= 8)))
            for k in range(20):
                self.assertEqual(tower.points(k), int(k + n >= 8))

    def test_one_object_source_has_only_identity_endomorphism(self):
        # Exhaust every Bool -> Bool function. Preserving both fixed points
        # forces the identity, independently of the selected infinite sequence.
        self.assertEqual([f for f in all_binary_maps() if preserves_base_points(f)], [(0, 1)])

    def test_forgetful_actions_on_maps_are_unchanged(self):
        # For each map X -> Y and point choices, preserving all named source
        # points entails preserving every point retained by either reduct.
        domain = (0, 1)
        codomain = (0, 1, 2)
        for f in itertools.product(codomain, repeat=2):
            for a, b, p, q in itertools.product(domain, repeat=4):
                source = Tower(domain, a, b, lambda n, p=p, q=q: (p, q)[n % 2])
                target = Tower(codomain, f[a], f[b], lambda n, source=source, f=f: f[source.points(n)])
                for n in range(8):
                    self.assertEqual(f[source.tail().points(n)], target.tail().points(n))
                self.assertEqual(f[source.head()[3]], target.head()[3])

    def test_all_small_transition_tables_against_independent_stepper(self):
        # Two states and a binary tape: 2*2=4 keys. For each key choose
        # halt, stay-in-0, move-to-1, or stay-in-1. All 4^4 tables are used.
        options = (None, Instruction(0, 0, 0), Instruction(1, 1, 1), Instruction(1, 0, -1))
        keys = tuple(itertools.product(range(2), range(2)))
        for choices in itertools.product(options, repeat=4):
            rows = tuple((q, a, ins) for (q, a), ins in zip(keys, choices) if ins is not None)
            machine = Machine(rows)
            table = {(q, a): ins for q, a, ins in rows}
            state = head = 0
            tape = {}
            halted = False
            for bound in range(13):
                ins = table.get((state, tape.get(head, 0)))
                halted = halted or ins is None
                self.assertEqual(machine.halts_within(bound), halted)
                if not halted:
                    tape[head] = ins.write
                    state = ins.next_state
                    head += ins.move

    def test_invalid_data_rejected(self):
        with self.assertRaises(ValueError):
            SelectedRoute(-1)
        with self.assertRaises(ValueError):
            Instruction(0, 3, 0)
        with self.assertRaises(ValueError):
            Machine(((0, 0, Instruction(0, 0, 0)), (0, 0, Instruction(0, 0, 0))))
        with self.assertRaises(ValueError):
            loop_forever().halts_within(-1)


if __name__ == "__main__":
    unittest.main(verbosity=2)

"""Executable finite models of the proposed contract corrections, not production tests."""
from dataclasses import dataclass
from itertools import permutations, product
import unittest

@dataclass(frozen=True)
class Binding:
    value: str
    role: str
    owners: frozenset[str]=frozenset()

@dataclass(frozen=True)
class Export:
    owner: str
    captures: tuple[Binding,...]

class Frame:
    def __init__(self, export, arguments, scope):
        self.export=export
        self.scope=scope
        self.slots=export.captures+tuple(arguments)
        self.active=True
    def capture(self, index):
        if not self.active or not (0<=index<len(self.export.captures)):
            raise ValueError('expired or undeclared capture')
        return self.slots[index]
    def required_owners(self):
        return frozenset({self.export.owner}).union(*(v.owners for v in self.slots))
    def dispatch(self, live):
        if not self.active or not self.required_owners()<=live:
            raise ValueError('unavailable before dispatch')
        return self.slots
    def close(self): self.active=False

class Admission:
    def __init__(self, nonce):
        self.nonce=nonce
        self.used=set()
        self.jobs=[]
    def receive(self, nonce, request_id, operation, payload):
        if nonce!=self.nonce:
            return 'wrong_nonce'
        if request_id in self.used:
            return 'protocol_error:duplicate_request_id'
        self.used.add(request_id)
        if operation=='execute':
            self.jobs.append((request_id,payload))
        return 'admitted'

class TransitionTests(unittest.TestCase):
    def setUp(self):
        self.a=Binding('original-map','map over R',frozenset({'foreign:1'}))
        self.b=Binding('other-map','map over S',frozenset({'foreign:2'}))
        self.exp=Export('producer:1',(self.a,self.b))
    def test_capture_prefix_cannot_be_replaced_by_arguments(self):
        for args in ((),(self.b,), (self.b,self.a)):
            f=Frame(self.exp,args,'fresh')
            self.assertEqual(tuple(f.capture(i) for i in range(2)),self.exp.captures)
            self.assertEqual(f.slots[2:],args)
    def test_equal_values_distinct_roles_retained(self):
        x=Binding('same','role-1'); y=Binding('same','role-2')
        f=Frame(Export('p',(x,y)),(),'s')
        self.assertNotEqual(f.capture(0),f.capture(1))
        self.assertEqual(len(f.slots),2)
    def test_nested_frames_do_not_mutate_shared_captures(self):
        first=Frame(self.exp,(self.a,),'s1'); second=Frame(self.exp,(self.b,),'s2')
        second.close()
        self.assertEqual(first.capture(0),self.a)
        self.assertEqual(first.slots[2],self.a)
        with self.assertRaises(ValueError): second.capture(0)
        self.assertEqual(self.exp.captures,(self.a,self.b))
    def test_suspend_rebinds_only_declared_capture_pairs(self):
        old=Frame(self.exp,(self.a,),'old')
        retained=(old.capture(1),)
        old.close()
        resume=Frame(Export(self.exp.owner,retained),(self.a,),'new')
        self.assertEqual(resume.capture(0),self.b)
        with self.assertRaises(ValueError): resume.capture(1)
        with self.assertRaises(ValueError): old.capture(0)
    def test_all_required_owners_checked_before_send(self):
        frame=Frame(self.exp,(Binding('arg','r',frozenset({'arg:1'})),),'s')
        allowners=frame.required_owners()
        self.assertEqual(allowners,frozenset({'producer:1','foreign:1','foreign:2','arg:1'}))
        for missing in allowners:
            with self.assertRaises(ValueError): frame.dispatch(allowners-{missing})
        self.assertEqual(frame.dispatch(allowners),frame.slots)
    def test_loss_after_preparation_does_not_rebind_owner(self):
        frame=Frame(self.exp,(),'s')
        replacement=frozenset({'producer:2','foreign:1','foreign:2'})
        with self.assertRaises(ValueError): frame.dispatch(replacement)
        self.assertEqual(frame.export.owner,'producer:1')
    def test_no_ambient_old_scope(self):
        frame=Frame(self.exp,(),'s')
        for i in (-1,2,7):
            with self.assertRaises(ValueError): frame.capture(i)
        frame.close()
        with self.assertRaises(ValueError): frame.capture(0)
    def test_duplicate_same_or_conflicting_payload_has_no_effect(self):
        for first,second in product(('code A','code B'),repeat=2):
            r=Admission('w')
            r.receive('w','i','execute',first)
            before=list(r.jobs)
            self.assertEqual(r.receive('w','i','execute',second),'protocol_error:duplicate_request_id')
            self.assertEqual(r.jobs,before)
    def test_request_id_shared_across_operation_kinds(self):
        for a,b in product(('execute','inspect','cancel','commit_status'),repeat=2):
            r=Admission('w'); r.receive('w','id',a,'payload')
            before=list(r.jobs)
            self.assertTrue(r.receive('w','id',b,'different').startswith('protocol_error:'))
            self.assertEqual(r.jobs,before)
    def test_no_snapshot_rollback_of_seen_identifiers(self):
        r=Admission('w'); r.receive('w','i','execute','A')
        # Snapshot selection deliberately does not mutate this live admission set.
        for snapshot in (0,1,0,9):
            self.assertTrue(r.receive('w','i','execute',f'parent={snapshot}').startswith('protocol_error:'))
        self.assertEqual(len(r.jobs),1)
    def test_explicit_rerun_fresh_id_is_not_a_duplicate(self):
        r=Admission('w')
        self.assertEqual(r.receive('w','i','execute','A'),'admitted')
        self.assertEqual(r.receive('w','j','execute','A'),'admitted')
        self.assertEqual(len(r.jobs),2)
    def test_wrong_nonce_cannot_consume_current_session_id(self):
        r=Admission('w')
        self.assertEqual(r.receive('old','i','execute','A'),'wrong_nonce')
        self.assertEqual(r.used,set())
        self.assertEqual(r.receive('w','i','execute','A'),'admitted')
    def test_serialized_competing_arrivals_allocate_once(self):
        for arrival in permutations(('A','B','C')):
            r=Admission('w')
            outcomes=[r.receive('w','same','execute',x) for x in arrival]
            self.assertEqual(outcomes.count('admitted'),1)
            self.assertEqual(len(r.jobs),1)
            self.assertEqual(r.jobs[0][1],arrival[0])
    def test_source_free_status_request_never_executes(self):
        r=Admission('w'); r.receive('w','i','execute','A')
        self.assertEqual(r.receive('w','status','commit_status','i'),'admitted')
        self.assertEqual(r.jobs,[('i','A')])

if __name__=='__main__': unittest.main(verbosity=2)

"""Finite engineering model for issue #69's observation/liveness correction.

These tests are not Lean/SDK execution or independent mathematical acceptance.
The model fixes immutable references first; observations have no callback or
execution capability. Computational use checks the selected dependency closure.
"""
from __future__ import annotations

from dataclasses import dataclass
from itertools import product
from types import MappingProxyType
import unittest


@dataclass(frozen=True)
class Ref:
    key: str
    role: str


@dataclass(frozen=True)
class Node:
    role: str
    kind: str
    fields: tuple[Ref, ...] = ()
    dependencies: tuple[Ref, ...] = ()
    owners: frozenset[str] = frozenset()


@dataclass(frozen=True)
class Descriptor:
    type_text: str
    field_labels: tuple[str, ...] = ()

    def __post_init__(self) -> None:
        if type(self.type_text) is not str or type(self.field_labels) is not tuple:
            raise TypeError('descriptors contain data, not render callbacks')
        if any(type(label) is not str for label in self.field_labels):
            raise TypeError('field labels must be inert strings')


class Unavailable(Exception):
    pass


class NeedsExecution(Exception):
    pass


class View:
    """A fixed snapshot or transaction-local graph supplied explicitly by its owner."""
    def __init__(self, nodes: dict[str, Node], descriptors: dict[str, Descriptor]):
        if set(nodes) != set(descriptors):
            raise ValueError('each visible node needs its inspection descriptor')
        for node in nodes.values():
            if node.kind not in ('portable', 'record', 'owned', 'closure', 'lazy'):
                raise ValueError('unknown operational node form')
            if node.kind != 'record' and node.fields:
                raise ValueError('only locally stored records have field references')
            for ref in node.fields + node.dependencies:
                if ref.key not in nodes or nodes[ref.key].role != ref.role:
                    raise ValueError('missing reference or mismatched prepared role')
        self.nodes = MappingProxyType(dict(nodes))
        self.descriptors = MappingProxyType(dict(descriptors))

    def node(self, ref: Ref) -> Node:
        node = self.nodes.get(ref.key)
        if node is None or node.role != ref.role:
            raise Unavailable('reference is not visible at its exact prepared role')
        return node

    def inspect(self, ref: Ref) -> Descriptor:
        self.node(ref)
        return self.descriptors[ref.key]

    def locate(self, ref: Ref, path: tuple[int, ...]) -> Ref:
        """Follow stored field identities only; never force an owned/lazy object."""
        self.node(ref)
        for slot in path:
            node = self.node(ref)
            if node.kind != 'record':
                raise NeedsExecution('no stored field at this position')
            if type(slot) is not int or not 0 <= slot < len(node.fields):
                raise Unavailable('not a declared field slot')
            ref = node.fields[slot]
            self.node(ref)
        return ref

    def required_owners(self, roots: tuple[Ref, ...]) -> frozenset[str]:
        """Complete operational closure of the chosen use, including all captures."""
        work = list(roots)
        seen: set[Ref] = set()
        owners: set[str] = set()
        while work:
            ref = work.pop()
            if ref in seen:
                continue
            node = self.node(ref)
            seen.add(ref)
            owners.update(node.owners)
            work.extend(node.dependencies)
            work.extend(node.fields)
        return frozenset(owners)

    def use(self, roots: tuple[Ref, ...], live: frozenset[str]) -> tuple[Ref, ...]:
        if not self.required_owners(roots) <= live:
            raise Unavailable('required generation is unavailable before dispatch')
        return roots


class ObservationContractTests(unittest.TestCase):
    def setUp(self) -> None:
        self.p = Ref('p', 'integer')
        self.h = Ref('h', 'selected map')
        self.r = Ref('r', 'joint result')
        self.c = Ref('c', 'capturing function')
        self.nodes = {
            'p': Node(self.p.role, 'portable'),
            'h': Node(self.h.role, 'owned', owners=frozenset({'engine:1'})),
            'r': Node(self.r.role, 'record', fields=(self.p, self.h)),
            'c': Node(self.c.role, 'closure', dependencies=(self.h,)),
        }
        self.docs = {key: Descriptor(node.role) for key, node in self.nodes.items()}
        self.view = View(self.nodes, self.docs)

    def test_portable_sibling_survives_owner_loss(self):
        actual = self.view.locate(self.r, (0,))
        self.assertIs(actual, self.p)
        self.assertEqual(self.view.use((actual,), frozenset()), (self.p,))

    def test_expired_selected_field_is_not_revived(self):
        actual = self.view.locate(self.r, (1,))
        self.assertIs(actual, self.h)
        with self.assertRaises(Unavailable):
            self.view.use((actual,), frozenset({'engine:2'}))

    def test_full_aggregate_still_requires_its_owners(self):
        with self.assertRaises(Unavailable):
            self.view.use((self.r,), frozenset())
        self.assertEqual(self.view.use((self.r,), frozenset({'engine:1'})), (self.r,))

    def test_all_declared_captures_remain_required(self):
        with self.assertRaises(Unavailable):
            self.view.use((self.c,), frozenset())
        self.assertEqual(self.view.required_owners((self.c,)), frozenset({'engine:1'}))

    def test_transitive_capture_and_argument_owners(self):
        outer = Ref('outer', 'export')
        argument = Ref('arg', 'argument')
        nodes = dict(self.nodes)
        nodes['outer'] = Node(outer.role, 'owned', dependencies=(self.c,), owners=frozenset({'producer:1'}))
        nodes['arg'] = Node(argument.role, 'owned', owners=frozenset({'argument:1'}))
        view = View(nodes, {k: Descriptor(n.role) for k, n in nodes.items()})
        needed = frozenset({'engine:1', 'producer:1', 'argument:1'})
        self.assertEqual(view.required_owners((outer, argument)), needed)
        for flags in product((False, True), repeat=3):
            live = frozenset(x for x, flag in zip(sorted(needed), flags) if flag)
            if all(flags):
                self.assertEqual(view.use((outer, argument), live), (outer, argument))
            else:
                with self.assertRaises(Unavailable): view.use((outer, argument), live)

    def test_nested_local_records_do_not_force_dead_siblings(self):
        root = Ref('root', 'outer record')
        nodes = dict(self.nodes)
        nodes['root'] = Node(root.role, 'record', fields=(self.h, self.r))
        view = View(nodes, {k: Descriptor(n.role) for k, n in nodes.items()})
        self.assertEqual(view.use((view.locate(root, (1, 0)),), frozenset()), (self.p,))

    def test_lazy_or_owned_projection_is_not_an_observation(self):
        for kind in ('owned', 'lazy'):
            ref = Ref('x', 'unmaterialized')
            view = View({'x': Node(ref.role, kind, owners=frozenset({'p:1'}))}, {'x': Descriptor(ref.role)})
            with self.assertRaises(NeedsExecution): view.locate(ref, (0,))

    def test_equal_roles_do_not_merge_distinct_values(self):
        other = Ref('other', self.p.role)
        nodes = dict(self.nodes)
        nodes['other'] = Node(other.role, 'portable')
        nodes['r'] = Node(self.r.role, 'record', fields=(self.p, other))
        view = View(nodes, {k: Descriptor(n.role) for k, n in nodes.items()})
        self.assertNotEqual(view.locate(self.r, (0,)), view.locate(self.r, (1,)))

    def test_receipt_association_is_not_whole_reply_liveness(self):
        # A previously admitted joint completion retains both actual output roots.
        receipt_roots = (self.p, self.h)
        self.assertEqual(self.view.use((receipt_roots[0],), frozenset()), (self.p,))
        with self.assertRaises(Unavailable): self.view.use((receipt_roots[1],), frozenset())
        self.assertEqual(receipt_roots, (self.p, self.h))

    def test_old_snapshot_cannot_find_new_values(self):
        old = View({'p': self.nodes['p']}, {'p': self.docs['p']})
        with self.assertRaises(Unavailable): old.locate(self.r, (0,))
        with self.assertRaises(Unavailable): old.use((self.h,), frozenset({'engine:1'}))

    def test_wrong_role_and_undeclared_field_are_rejected(self):
        with self.assertRaises(Unavailable): self.view.node(Ref('p', 'another meaning'))
        for path in ((2,), (-1,), (True,)):
            with self.assertRaises(Unavailable): self.view.locate(self.r, path)

    def test_inert_inspection_cannot_reach_registered_callbacks(self):
        effects = []
        def extension_printer():
            effects.append('owner closed')
            return 'pretty type'
        # This is the unsafe architectural path, modeled as an ordinary callback.
        self.assertEqual(extension_printer(), 'pretty type')
        self.assertEqual(effects, ['owner closed'])
        effects.clear()
        for _ in range(5):
            self.assertEqual(self.view.inspect(self.h), self.docs['h'])
        self.assertEqual(effects, [])

    def test_descriptors_cannot_hide_deferred_rendering(self):
        with self.assertRaises(TypeError): Descriptor(lambda: 'executed later')
        with self.assertRaises(TypeError): Descriptor('type', (lambda: 'field',))

    def test_snapshot_is_not_mutated_by_later_input_changes(self):
        self.nodes.clear()
        self.docs['p'] = Descriptor('changed')
        self.assertEqual(self.view.inspect(self.p).type_text, 'integer')
        self.assertEqual(self.view.locate(self.r, (0,)), self.p)

    def test_missing_descriptor_cannot_publish_partial_query_view(self):
        with self.assertRaises(ValueError): View(self.nodes, {'p': self.docs['p']})

    def test_inspection_of_expired_value_does_not_claim_live_execution(self):
        self.assertEqual(self.view.inspect(self.h).type_text, self.h.role)
        with self.assertRaises(Unavailable): self.view.use((self.h,), frozenset())


if __name__ == '__main__':
    unittest.main(verbosity=2)

"""Whole product cones and native mediator continuations for occurrence controls."""

from __future__ import annotations

import json
import sys
from pathlib import Path

from cas_port import input_ref, serve
from cas_session import export, proxy, suspend

configuration = json.loads(sys.argv[1])
apex = {"ctor": "finiteData", "args": ["original-product", [[0, 0]]]}


def observe(operation, arguments):
    with Path(configuration["log"]).open("a", encoding="utf-8") as log:
        log.write(json.dumps({"op": operation, "args": arguments}) + "\n")


def construction(arguments):
    observe("lim.sets.product", arguments)
    assert arguments["ctor"] == "pair" and len(arguments["args"]) == 2
    endpoints = [proxy(input_ref(["args", index])) for index in range(2)]
    maps = [
        {"ctor": "typedMap", "args": [
            apex, endpoint.reference(),
            {"ctor": "finiteGraph", "args": [[[0, 0]], [[[0, 0], 0]]]},
        ]}
        for endpoint in endpoints
    ]
    return {"ctor": "cone", "args": [apex, *maps]}


def mediator(arguments):
    observe("lim.sets.product#isLimit", arguments)
    assert arguments["prepared_role"].endswith("IsLimit.lift")
    assert len(arguments["bindings"]) == 1 and arguments["bindings"][0]["slot"] == 0
    assert len(arguments["arguments"]) == 1
    target_cone = proxy(input_ref(["bindings", 0, "value"]))
    source_cone = proxy(input_ref(["arguments", 0]))
    points = yield suspend(
        [source_cone.project(0), target_cone.project(0)],
        [source_cone, target_cone],
    )
    source, target = points
    if configuration["mode"] == "wrong-target":
        target = source

    def apply_mediator(context):
        observe("mediator-application", context)
        assert len(context["arguments"]) == 1
        return input_ref(["arguments", 0])

    return {"ctor": "typedMap", "args": [
        source.reference(), target.reference(),
        export(apply_mediator, [source, target]),
    ]}


serve("universal-construction-peer", "0", {
    "lim.sets.product": construction,
    "lim.sets.product#isLimit": mediator,
})

#!/usr/bin/env python3
"""Resolve own-organisation Lake requires only when fetched main changed."""

import json
import subprocess
import sys
from pathlib import Path


OWN_REQUIRES = ("lean_categories", "cas_leaf_contracts", "nbdsl-worker")


def resolved_revisions(root: Path) -> dict[str, str]:
    manifest = json.loads((root / "lake-manifest.json").read_text())
    revisions = {}
    for entry in manifest["packages"]:
        name = entry["name"].removeprefix("«").removesuffix("»")
        if name in OWN_REQUIRES:
            revisions[name] = entry["rev"]
    missing = set(OWN_REQUIRES) - revisions.keys()
    if missing:
        raise RuntimeError(f"Lake manifest lacks own requires: {', '.join(sorted(missing))}")
    return revisions


def stale_requires(root: Path) -> list[str]:
    resolved = resolved_revisions(root)
    stale = []
    for name in OWN_REQUIRES:
        checkout = root / ".lake" / "packages" / name
        head = subprocess.check_output(
            ["git", "-C", str(checkout), "rev-parse", "HEAD"], text=True).strip()
        if resolved[name] != head:
            stale.append(name)
    return stale


def main() -> None:
    if len(sys.argv) > 2:
        raise SystemExit("usage: resolve_lake_if_needed.py [checkout]")
    root = Path(sys.argv[1]) if len(sys.argv) == 2 else Path(__file__).resolve().parent.parent
    stale = stale_requires(root)
    if stale:
        print(f"Resolving changed latest-main requires: {', '.join(stale)}", flush=True)
        subprocess.run(["lake", "update", *stale], cwd=root, check=True)
    else:
        print("Own-organisation Lake requires already resolve to fetched main; skip update")


if __name__ == "__main__":
    main()

"""CI must inspect every original result, including nonfailing computation gaps."""

import copy
import unittest

from ci_kernel_candidate import check_fixed_controls, check_fixed_execution


class FixedExecutionTests(unittest.TestCase):
    def setUp(self):
        self.expected = {'original.one': {'file': '/fixed/one.cas'},
                         'original.two': {'file': '/fixed/two.cas'}}
        self.rows = [{'id': identity, 'file': source['file'], 'kind': 'holds',
                      'fails': False, 'question': 'complete question ' + identity,
                      'proposition': 'complete proposition ' + identity, 'dispatches': []}
                     for identity, source in self.expected.items()]

    def test_complete_original_results(self):
        self.assertEqual(check_fixed_execution(self.rows, self.expected), [])

    def test_zero_exit_nonfailing_gaps_are_not_completion(self):
        for kind in ['gap', 'unavailable', 'wrong', 'invalid', 'internal', 'malformed', 'ambiguous']:
            rows = copy.deepcopy(self.rows)
            rows[0].update(kind=kind, fails=False)
            self.assertTrue(check_fixed_execution(rows, self.expected), kind)

    def test_missing_duplicate_reordered_or_additional_results_fail(self):
        for rows in [[], self.rows[:1], self.rows + self.rows[:1], list(reversed(self.rows)),
                     [*self.rows, {'id': '(statement) failed binding', 'kind': 'internal'}]]:
            self.assertTrue(check_fixed_execution(rows, self.expected))

    def test_reading_source_and_dispatch_records_are_required(self):
        for key, value in [('file', '/different/source.cas'), ('question', ''),
                           ('proposition', None), ('dispatches', None), ('fails', True)]:
            rows = copy.deepcopy(self.rows)
            rows[0][key] = value
            self.assertTrue(check_fixed_execution(rows, self.expected), key)


class FixedControlTests(unittest.TestCase):
    def rx10(self):
        return {'observations': [
            {'condition': condition, 'expectedKind': condition, 'kind': condition,
             'id': 'original.rx10', 'source': 'original fixed source', 'sourceLine': 11,
             'question': 'complete original question', 'proposition': 'complete proposition',
             'sameIndependentTypedQuestion': True, 'callableReused': True,
             'sessionControls': {'kind': 'holds'}}
            for condition in ['holds', 'gap', 'unavailable', 'malformed', 'wrong', 'internal']]}

    def test_rx10_requires_all_six_exact_outcomes(self):
        document = self.rx10()
        self.assertEqual(check_fixed_controls('rx10', document), [])
        malformed = self.rx10()
        malformed['observations'].append(None)
        self.assertTrue(check_fixed_controls('rx10', malformed))
        for index in range(6):
            missing = self.rx10()
            missing['observations'].pop(index)
            self.assertTrue(check_fixed_controls('rx10', missing))
            wrong = self.rx10()
            wrong['observations'][index]['kind'] = 'different'
            self.assertTrue(check_fixed_controls('rx10', wrong))

    def test_rx10_cannot_hide_changed_question_or_unconsumed_callable(self):
        for index, key, value in [(1, 'question', 'changed'), (2, 'proposition', ''),
                                  (4, 'callableReused', False), (0, 'callableReused', False),
                                  (0, 'sessionControls', {'kind': 'internal'}),
                                  (3, 'sameIndependentTypedQuestion', False)]:
            document = self.rx10()
            document['observations'][index][key] = value
            self.assertTrue(check_fixed_controls('rx10', document), (index, key))

    def test_rx09_requires_the_original_admission_boundary(self):
        row = {'control': 'RX09', 'kind': 'invalid', 'stage': 'admission',
               'prerequisites': 4, 'dispatches': [],
               'actualAttempt': {'terms': []}, 'independentObligation': {'terms': []}}
        self.assertEqual(check_fixed_controls('rx09', [row]), [])
        for key, value in [('kind', 'internal'), ('stage', 'parse'), ('prerequisites', 3),
                           ('dispatches', [{}]), ('actualAttempt', None),
                           ('independentObligation', None)]:
            self.assertTrue(check_fixed_controls('rx09', [{**row, key: value}]), key)

    def test_rx05_rejects_incomplete_environment_and_typed_comparison_reports(self):
        self.assertTrue(check_fixed_controls('rx05', []))
        environments = [{'environment': name, 'selectedInventory': {}, 'typedReceiver': {},
                         'resolutionKind': 'resolved' if index < 2 else 'ambiguous',
                         'typedRequest': {}, 'candidates': [{}],
                         'registryApplicableCandidates': [{}], 'completeRegistryInventoryRetained': True}
                        for index, name in enumerate(['present', 'present-reversed', 'absent', 'absent-reversed'])]
        row = {'control': 'RX05', 'environments': environments, 'crossEnvironmentChecks': {
            'presentResolutionMetadataEqual': True, 'presentCompleteTypedRequestsEquivalent': True,
            'absentCompleteCandidatesEquivalentAsMultisets': True,
            'registryApplicableInventoriesEquivalentAsMultisets': True}}
        self.assertEqual(check_fixed_controls('rx05', [row]), [])
        malformed = copy.deepcopy(row)
        malformed['environments'].append(None)
        self.assertTrue(check_fixed_controls('rx05', [malformed]))
        for key in row['crossEnvironmentChecks']:
            bad = copy.deepcopy(row)
            bad['crossEnvironmentChecks'][key] = False
            self.assertTrue(check_fixed_controls('rx05', [bad]), key)
        bad = copy.deepcopy(row)
        bad['environments'][2]['candidates'] = []
        self.assertTrue(check_fixed_controls('rx05', [bad]))


if __name__ == '__main__':
    unittest.main()
